//! 📑️ A second metadata owner is prepared from the exact moved original and restores it before handoff or cancellation.
use super::ActionMeta;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneSourceTake,RetainedCloneCursor,RetainedFieldCursor,RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
/// 🧷️ The owner slot remains empty only while this exact original occupies its funded source.
pub struct OriginalActionMetaCopy{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,source:ManuallyDrop<Option<RetainedCloneSource<ActionMeta>>>,cursor:RetainedFieldCursor<ActionMeta>,output:ManuallyDrop<Option<ActionMeta>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"metadata copy changed its original owner, caller or receiving continuation")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalActionMetaCopy{
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;admit_original_construction(cx,output,original(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{binding,decoder,body,source:ManuallyDrop::new(None),cursor:Default::default(),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}),progress(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn paid(cx:&mut StepContext<'_>,d:RetirementDemand)->Result<bool,OriginalTurnFailure>{let mut output=None;admit_original_construction(cx,&mut output,original(d),|_|Ok(((),progress(d))))}
 pub fn advance(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}match self.phase{
  0=>{if owner.is_none(){return Err(invalid().into())}let birth=RetainedCloneSource::<ActionMeta>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<ActionMeta>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,release_bytes:0,depth:birth.depth};let g=cx.retained_grant();if admit_original_construction(cx,&mut self.source,original(d),|_|{let meta=owner.take().unwrap();match RetainedCloneSource::admit_owned(meta,(),g){Ok(value)=>Ok(value),Err((error,meta,()))=>{*owner=Some(meta);Err(error)}}})?{self.phase=1}},
  1=>{let source=self.source.as_ref().unwrap().borrow();if self.cursor.output_ready(){let d=fixed::<Option<ActionMeta>>();if Self::paid(cx,d)?{*self.output=self.cursor.take();self.cursor.begin_close();self.phase=2}}else{let d=self.cursor.advance_demands(source,self.body)?;if !cx.should_yield()&&retained_clone_grant_admits(cx.retained_grant(),d){let result=cx.with_native_receiving::<_,semio_framework_value_native_owned::native_decoding::NativeConstructionStepFailure<ValueError>>(|native|native.receive_construction_step(d,|control,g|{control.charge(d.capacity_bytes)?;self.cursor.advance(source,self.body,g)}));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let reconciled=cx.receiving_issued_grant().map(|g|cx.consume_receiving_retained(g,p)).transpose();cx.consume_fuel(p.copied_items as u64);match(result,reconciled){(Ok(_),Ok(_))=>{},(Err(error),Ok(_))=>return Err(error.into()),(Ok(_),Err(error))=>return Err(error.into()),(Err(error),Err(receipt))=>{let mut error=OriginalTurnFailure::from(error);error.context_refusal=Some(receipt);return Err(error)}}}}},
  2=>{if self.restore(owner,cx)?&&Self::paid(cx,fixed::<u8>())?{self.phase=3}},
  3|4=>return Ok(true),_=>return Err(invalid().into())}Ok(self.phase>=3)}
 fn restore(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.cursor.begin_close();if !self.cursor.terminal_is_empty(){let d=self.cursor.close_demands(self.body)?;close_original_retained_step(cx,d,|g|self.cursor.close_step(g))?;return Ok(false)}if let Some(source)=self.source.as_mut(){if owner.is_some(){return Err(invalid().into())}let d=source.next_take_demand(self.body)?;let g=cx.retained_grant();if !cx.should_yield()&&retained_clone_grant_admits(g,d){let p=match source.take_authority(g)?{RetainedCloneSourceTake::Pending(p)=>p,RetainedCloneSourceTake::Ready(meta,p)=>{*owner=Some(meta);self.source.take();p}};cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)}return Ok(false)}Ok(true)}
 pub fn take_into(&mut self,output:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=3||self.closing||output.is_some(){return Err(invalid().into())}if !Self::paid(cx,fixed::<Option<ActionMeta>>())?{return Ok(false)}*output=self.output.take();self.phase=4;Ok(true)}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(fixed::<u8>())}if !self.cursor.terminal_is_empty(){return self.cursor.close_demands(self.body)}if let Some(source)=self.source.as_ref(){return source.next_take_demand(self.body)}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.output.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.closing{let d=fixed::<u8>();close_original_retained_step(cx,d,|_|{self.closing=true;self.cursor.begin_close();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}if !self.restore(owner,cx)?{return Ok(false)}if !self.retirement.is_empty(){let selected=self.retirement.select(self.body)?;let d=selected.demands();close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}if self.output.is_some(){let d=self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)?;close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.output,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.cursor.terminal_is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalActionMetaCopy{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"metadata copy requires original restoration and paid closure")}}
